// Knowledge map: an Obsidian-style force graph of published notes and the links between them.
// Data: map/graph.json, generated by tools/sync.py. Colours follow the active palette.
(function () {
  const host = document.getElementById("kmap");
  if (!host || typeof d3 === "undefined") return;

  const css = (name) => getComputedStyle(document.body).getPropertyValue(name).trim();
  const isHub = (n) => n.kind === "thread";  // threads are the hubs (report/ workflow)
  const nodeColor = (n) => (isHub(n) ? css("--c-surface") : {
    progress: css("--c-chip-progress"),
    analysis: css("--c-chip-analysis"),
    plan: css("--c-node-plan"),
    note: css("--c-node-scratch"),
  }[n.kind] || css("--c-node-note"));

  fetch("graph.json").then((r) => r.json()).then((graph) => {
    const nodes = graph.nodes.map((n) => ({ ...n }));
    const byId = new Map(nodes.map((n) => [n.id, n]));
    const links = graph.links.filter((l) => byId.has(l.source) && byId.has(l.target)).map((l) => ({ ...l }));
    const degree = new Map(nodes.map((n) => [n.id, 0]));
    const neighbours = new Map(nodes.map((n) => [n.id, new Set([n.id])]));
    for (const l of links) {
      degree.set(l.source, degree.get(l.source) + 1);
      degree.set(l.target, degree.get(l.target) + 1);
      neighbours.get(l.source).add(l.target);
      neighbours.get(l.target).add(l.source);
    }
    const radius = (n) => (isHub(n) ? 7 : 3.5) + Math.sqrt(degree.get(n.id)) * 1.6;

    const width = host.clientWidth || 900;
    const height = host.clientHeight || 600;
    const svg = d3.select(host).append("svg").attr("viewBox", [-width / 2, -height / 2, width, height]);
    const view = svg.append("g");
    svg.call(d3.zoom().scaleExtent([0.3, 4]).on("zoom", (e) => view.attr("transform", e.transform)));

    const link = view.append("g").attr("class", "kmap-links").selectAll("line").data(links).join("line");
    const node = view.append("g").selectAll("g").data(nodes).join("g").attr("class", "kmap-node");
    node.append("circle").attr("r", radius);
    node.append("title").text((n) => n.title + (n.date ? ` (${n.date})` : ""));
    const label = node.append("text")
      .attr("x", (n) => radius(n) + 3).attr("y", 3)
      .attr("class", (n) => (isHub(n) ? "kmap-label hub" : "kmap-label"))
      .text((n) => n.title);

    const paint = () => {
      node.select("circle").attr("fill", nodeColor)
        .attr("stroke", (n) => (isHub(n) ? css("--c-green") : css("--c-bg")))
        .attr("stroke-width", (n) => (isHub(n) ? 3 : 1.5));
      link.attr("stroke", css("--c-line"));
      label.attr("fill", css("--c-text"));
    };
    paint();
    new MutationObserver(paint).observe(document.body, { attributes: true, attributeFilter: ["data-md-color-scheme"] });

    node.on("mouseenter", (e, n) => {
      const near = neighbours.get(n.id);
      node.classed("dim", (m) => !near.has(m.id)).classed("lit", (m) => near.has(m.id));
      link.classed("dim", (l) => l.source.id !== n.id && l.target.id !== n.id)
        .classed("lit", (l) => l.source.id === n.id || l.target.id === n.id);
    }).on("mouseleave", () => {
      node.classed("dim", false).classed("lit", false);
      link.classed("dim", false).classed("lit", false);
    }).on("click", (e, n) => { window.location.href = n.url; });

    const sim = d3.forceSimulation(nodes)
      .force("link", d3.forceLink(links).id((n) => n.id).distance((l) => (isHub(l.source) || isHub(l.target) ? 95 : 60)))
      .force("charge", d3.forceManyBody().strength((n) => (isHub(n) ? -420 : -140)))
      .force("collide", d3.forceCollide().radius((n) => radius(n) + 4))
      .force("x", d3.forceX().strength(0.04))
      .force("y", d3.forceY().strength(0.06))
      .on("tick", () => {
        link.attr("x1", (l) => l.source.x).attr("y1", (l) => l.source.y)
          .attr("x2", (l) => l.target.x).attr("y2", (l) => l.target.y);
        node.attr("transform", (n) => `translate(${n.x},${n.y})`);
      });

    node.call(d3.drag()
      .on("start", (e, n) => { if (!e.active) sim.alphaTarget(0.3).restart(); n.fx = n.x; n.fy = n.y; })
      .on("drag", (e, n) => { n.fx = e.x; n.fy = e.y; })
      .on("end", (e, n) => { if (!e.active) sim.alphaTarget(0); n.fx = null; n.fy = null; }));
  });
})();
